import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { checkout } from './src/app.js';
import { makeReceiptKey } from './src/billing/receipt.js';
import { makeReceiptKey as reportKey } from './src/reports/receipt.js';
import { makeReceiptKey as responseReceipt } from './src/transport/receipt.js';
const answer = JSON.parse(readFileSync('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['owner_file', 'owner_symbol', 'outbound_file', 'outbound_symbol', 'call_chain', 'example_key']);
const invoice = { accountId: 'acme', sequence: 7 };
assert.equal(makeReceiptKey(invoice), answer.example_key);
assert.equal(reportKey({ id: 7 }), 'report:7');
assert.equal(responseReceipt({ headers: { 'x-receipt': 'receipt-7' } }), 'receipt-7');
let calls = 0;
await checkout(invoice, { post(path, body, headers) {
  calls++;
  assert.equal(path, '/invoices');
  assert.equal(body, invoice);
  assert.deepEqual(headers, { 'Idempotency-Key': answer.example_key });
} });
assert.equal(calls, 1);
console.log('PASS: answer.json schema, key construction, distinct receipt helpers, and checkout outbound header.');
JS"

